const v1v2Panel = (x, id, name, title, verdict, color, note) => `<g data-hotspot="${id}" data-label="${name}">
    <rect x="${x}" y="8" width="304" height="250" rx="10" style="fill:var(--c-surface);stroke:var(--c-border)"/>
    <text x="${x + 152}" y="34" font-size="16" font-weight="700" text-anchor="middle" style="fill:var(--c-text)">${title}</text>
    <line x1="${x + 16}" y1="190" x2="${x + 288}" y2="190" style="stroke:var(--c-muted);stroke-width:1"/>
    <line x1="${x + 16}" y1="130" x2="${x + 288}" y2="130" style="stroke:var(--viz-enter);stroke-width:2;stroke-dasharray:8 5"/>
    <text x="${x + 284}" y="124" font-size="13" text-anchor="end" style="fill:var(--viz-enter)">25°</text>
    <polyline points="${x + 16},190 ${x + 60},190 ${x + 90},96 ${x + 210},96 ${x + 240},190 ${x + 288},190" style="fill:none;stroke:var(--viz-g);stroke-width:4;stroke-linejoin:round"/>
    <text x="${x + 150}" y="86" font-size="13" text-anchor="middle" style="fill:var(--c-muted)">uống nước, giữ ≈ 1 s</text>
    <text x="${x + 152}" y="62" font-size="16" font-weight="700" text-anchor="middle" style="fill:${color}">${verdict}</text>
    <text x="${x + 152}" y="218" font-size="13" text-anchor="middle" style="fill:var(--c-text)">${note}</text>
    <text x="${x + 152}" y="242" font-size="12" text-anchor="middle" style="fill:var(--c-muted)">thời gian →</text>
  </g>`;

const SVG_HELP_V1_V2 = `<svg viewBox="0 0 640 266" xmlns="http://www.w3.org/2000/svg" role="img" font-family="inherit">
  ${v1v2Panel(8, 'v1', 'Bản nháp: gập và giữ 400 ms', 'Bản nháp: gập + giữ 400 ms', '✗ HELP nhầm!', 'var(--c-danger)', 'giữ quá 400 ms → bị tính là HELP')}
  ${v1v2Panel(328, 'v2', 'Bản hiện tại: nhấp 2 lần', 'Bản hiện tại: nhấp 2 lần', '✓ Không phát', 'var(--c-success)', 'ở ngoài quá 700 ms → không phải nhấp')}
</svg>`;

