          svg: '<svg viewBox="0 0 600 300" xmlns="http://www.w3.org/2000/svg" font-family="inherit" role="img"><line x1="60" y1="240" x2="580" y2="240" stroke="currentColor" stroke-width="2"/><line x1="60" y1="30" x2="60" y2="240" stroke="currentColor" stroke-width="2"/><text x="8" y="44" font-size="14" fill="currentColor">góc</text><text x="520" y="266" font-size="14" fill="currentColor">thời gian</text><line x1="60" y1="100" x2="580" y2="100" stroke="var(--viz-enter)" stroke-width="2" stroke-dasharray="8 6"/><text x="4" y="105" font-size="14" fill="var(--viz-enter)">25°</text><line x1="60" y1="160" x2="580" y2="160" stroke="var(--viz-exit)" stroke-width="2" stroke-dasharray="2 5"/><text x="4" y="165" font-size="14" fill="var(--viz-exit)">12°</text><polyline points="60,225 100,225 125,60 165,60 190,225 250,225 275,60 315,60 340,225 580,225" fill="none" stroke="var(--viz-y)" stroke-width="4" stroke-linejoin="round"/><text x="108" y="48" font-size="14" fill="currentColor">Lần nhấp 1</text><text x="258" y="48" font-size="14" fill="currentColor">Lần nhấp 2</text><line x1="110" y1="200" x2="185" y2="200" stroke="currentColor" stroke-width="2"/><text x="112" y="194" font-size="14" fill="currentColor">≤ 700 ms</text><line x1="110" y1="280" x2="335" y2="280" stroke="var(--c-primary)" stroke-width="2"/><text x="150" y="274" font-size="14" fill="var(--c-primary)">cả hai trong ≤ 2000 ms</text><rect x="380" y="60" width="110" height="40" rx="10" fill="var(--c-danger-bg)" stroke="var(--c-danger)" stroke-width="2"/><text x="400" y="86" font-size="16" font-weight="700" fill="currentColor">→ HELP</text></svg>',
